import type { Vec3 } from '../../contracts/math';
import type { PlayerId } from '../../contracts/game';
import type { ZoneBounds, ZoneType, ZoneTriggerEvent, IZone } from '../../contracts/zones';

export abstract class BaseZone implements IZone {
  constructor(
    public readonly id: string,
    public readonly type: ZoneType,
    public readonly bounds: ZoneBounds,
    public readonly penaltyStrokes: number = 1,
    public readonly resetPosition?: Vec3
  ) {}

  contains(position: Vec3): boolean {
    return (
      position.x >= this.bounds.min.x && position.x <= this.bounds.max.x &&
      position.y >= this.bounds.min.y && position.y <= this.bounds.max.y &&
      position.z >= this.bounds.min.z && position.z <= this.bounds.max.z
    );
  }

  onTrigger(playerId: PlayerId, position: Vec3): ZoneTriggerEvent {
    return {
      playerId,
      zoneId: this.id,
      zoneType: this.type,
      position: { ...position }
    };
  }

  resolveHazard(lastSafePosition: Vec3): { resetPosition: Vec3; penaltyStrokes: number } {
    return {
      resetPosition: this.resetPosition ?? lastSafePosition,
      penaltyStrokes: this.penaltyStrokes
    };
  }
}
EOF
