import { BaseZone } from './BaseZone';
import type { Vec3 } from '../../contracts/math';
import type { ZoneBounds } from '../../contracts/zones';

export class GravityZone extends BaseZone {
  constructor(
    id: string,
    bounds: ZoneBounds,
    public readonly strength: number = 9.81,
    public readonly direction: Vec3 = { x: 0, y: -1, z: 0 }
  ) {
    super(id, 'gravity', bounds, 0, undefined);
  }

  getForce(_position: Vec3, _velocity: Vec3, mass: number): Vec3 {
    return {
      x: this.direction.x * this.strength * mass,
      y: this.direction.y * this.strength * mass,
      z: this.direction.z * this.strength * mass
    };
  }
}
